from pathlib import Path

source_path = Path("paper/src/main/java/net/enthusia/staff/paper/freeze/FreezeStaffNotifier.java")
source_path.write_text("""package net.enthusia.staff.paper.freeze;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport net.enthusia.staff.domain.auth.Actor;\nimport net.enthusia.staff.domain.player.PlayerIdentity;\nimport net.enthusia.staff.paper.auth.PaperStaffRankResolver;\nimport net.kyori.adventure.text.Component;\nimport net.kyori.adventure.text.event.ClickEvent;\nimport net.kyori.adventure.text.event.HoverEvent;\nimport net.kyori.adventure.text.format.NamedTextColor;\nimport org.bukkit.entity.Player;\nimport org.bukkit.plugin.Plugin;\nimport org.bukkit.plugin.java.JavaPlugin;\n\npublic final class FreezeStaffNotifier implements FreezeAlertSink {\n    private final JavaPlugin plugin;\n\n    public FreezeStaffNotifier(JavaPlugin plugin) {\n        this.plugin = java.util.Objects.requireNonNull(plugin, \"plugin\");\n    }\n\n    @Override\n    public void frozen(PlayerIdentity target, Actor actor, String reason) {\n        announce(target, actor, reason, true);\n    }\n\n    @Override\n    public void unfrozen(PlayerIdentity target, Actor actor, String reason) {\n        announce(target, actor, reason, false);\n    }\n\n    private void announce(PlayerIdentity target, Actor actor, String reason, boolean frozen) {\n        Component message = render(target, actor, reason, frozen);\n        plugin.getServer().getGlobalRegionScheduler().execute(plugin, () -> {\n            List<Player> online = new ArrayList<>(plugin.getServer().getOnlinePlayers());\n            online.forEach(player -> scheduleRecipient(plugin, player, message));\n        });\n    }\n\n    static Component render(PlayerIdentity target, Actor actor, String reason, boolean frozen) {\n        String targetName = target.currentUsername().orElse(target.playerId().toString());\n        Component message = Component.text(\"[Freeze] \", NamedTextColor.GOLD)\n                .append(Component.text(targetName, NamedTextColor.YELLOW))\n                .append(Component.text(frozen ? \" frozen by \" : \" unfrozen by \", NamedTextColor.GRAY))\n                .append(Component.text(actor.displayName(), NamedTextColor.AQUA))\n                .append(Component.text(\" — \" + reason, NamedTextColor.GRAY));\n        if (target.currentUsername().isEmpty()) {\n            return message;\n        }\n        Component teleport = Component.text(\" [Teleport]\", NamedTextColor.GREEN)\n                .clickEvent(ClickEvent.runCommand(\"/tp \" + targetName))\n                .hoverEvent(HoverEvent.showText(Component.text(\"Teleport to \" + targetName)));\n        return message.append(teleport);\n    }\n\n    static boolean scheduleRecipient(Plugin plugin, Player player, Component message) {\n        try {\n            return player.getScheduler().execute(plugin, () -> {\n                if (isStaff(player)) {\n                    player.sendMessage(message);\n                }\n            }, null, 1L);\n        } catch (RuntimeException exception) {\n            return false;\n        }\n    }\n\n    private static boolean isStaff(Player player) {\n        return PaperStaffRankResolver.resolve(player::hasPermission).isPresent();\n    }\n}\n""", encoding="utf-8")

test_path = Path("paper/src/test/java/net/enthusia/staff/paper/freeze/FreezeStaffNotifierTest.java")
test_path.write_text("""package net.enthusia.staff.paper.freeze;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nimport io.papermc.paper.threadedregions.scheduler.EntityScheduler;\nimport java.lang.reflect.Method;\nimport java.lang.reflect.Proxy;\nimport java.time.Instant;\nimport java.util.Optional;\nimport java.util.UUID;\nimport java.util.concurrent.atomic.AtomicBoolean;\nimport net.enthusia.staff.domain.auth.Actor;\nimport net.enthusia.staff.domain.auth.StaffRank;\nimport net.enthusia.staff.domain.player.PlayerIdentity;\nimport net.enthusia.staff.domain.player.PlayerPlatform;\nimport net.kyori.adventure.text.Component;\nimport net.kyori.adventure.text.event.ClickEvent;\nimport net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer;\nimport org.bukkit.entity.Player;\nimport org.bukkit.plugin.Plugin;\nimport org.junit.jupiter.api.Test;\n\nclass FreezeStaffNotifierTest {\n    private static final Instant NOW = Instant.parse(\"2026-09-23T12:00:00Z\");\n\n    @Test\n    void freezeAlertNamesActorTargetReasonAndProvidesTeleportAction() {\n        PlayerIdentity target = new PlayerIdentity(\n                UUID.fromString(\"11111111-1111-1111-1111-111111111111\"),\n                Optional.of(\"Target\"),\n                PlayerPlatform.JAVA,\n                NOW,\n                NOW\n        );\n        Actor actor = new Actor(\n                UUID.fromString(\"22222222-2222-2222-2222-222222222222\"),\n                \"Moderator\",\n                StaffRank.MOD\n        );\n\n        Component message = FreezeStaffNotifier.render(target, actor, \"screenshare\", true);\n        String plain = PlainTextComponentSerializer.plainText().serialize(message);\n\n        assertTrue(plain.contains(\"Target frozen by Moderator\"));\n        assertTrue(plain.contains(\"screenshare\"));\n        Component teleport = message.children().getLast();\n        assertEquals(ClickEvent.runCommand(\"/tp Target\"), teleport.clickEvent());\n    }\n\n    @Test\n    void offlineIdentityDoesNotOfferBrokenTeleportAction() {\n        PlayerIdentity target = new PlayerIdentity(\n                UUID.fromString(\"33333333-3333-3333-3333-333333333333\"),\n                Optional.empty(),\n                PlayerPlatform.UNKNOWN,\n                NOW,\n                NOW\n        );\n        Actor actor = new Actor(\n                UUID.fromString(\"44444444-4444-4444-4444-444444444444\"),\n                \"Admin\",\n                StaffRank.ADMIN\n        );\n\n        Component message = FreezeStaffNotifier.render(target, actor, \"release\", false);\n\n        assertTrue(message.children().stream().noneMatch(child -> child.clickEvent() != null));\n    }\n\n    @Test\n    void staffCheckAndDeliveryRunOnlyOnRecipientEntityScheduler() {\n        AtomicBoolean owned = new AtomicBoolean();\n        AtomicBoolean permissionChecked = new AtomicBoolean();\n        AtomicBoolean delivered = new AtomicBoolean();\n        Runnable[] entityTask = new Runnable[1];\n        EntityScheduler scheduler = scheduler((plugin, action, retired, delay) -> {\n            assertEquals(1L, delay);\n            entityTask[0] = action;\n            return true;\n        });\n        Player player = player(scheduler, owned, permissionChecked, delivered);\n\n        boolean scheduled = FreezeStaffNotifier.scheduleRecipient(\n                plugin(),\n                player,\n                Component.text(\"freeze alert\")\n        );\n\n        assertTrue(scheduled);\n        assertFalse(permissionChecked.get());\n        assertFalse(delivered.get());\n        owned.set(true);\n        entityTask[0].run();\n        assertTrue(permissionChecked.get());\n        assertTrue(delivered.get());\n    }\n\n    @Test\n    void rejectedEntitySchedulingDoesNotTouchRecipientState() {\n        AtomicBoolean permissionChecked = new AtomicBoolean();\n        AtomicBoolean delivered = new AtomicBoolean();\n        EntityScheduler scheduler = scheduler((plugin, action, retired, delay) -> false);\n        Player player = player(scheduler, new AtomicBoolean(), permissionChecked, delivered);\n\n        boolean scheduled = FreezeStaffNotifier.scheduleRecipient(\n                plugin(),\n                player,\n                Component.text(\"freeze alert\")\n        );\n\n        assertFalse(scheduled);\n        assertFalse(permissionChecked.get());\n        assertFalse(delivered.get());\n    }\n\n    private static Player player(\n            EntityScheduler scheduler,\n            AtomicBoolean owned,\n            AtomicBoolean permissionChecked,\n            AtomicBoolean delivered\n    ) {\n        return proxy(Player.class, (method, arguments) -> {\n            if (method.getName().equals(\"getScheduler\")) {\n                return scheduler;\n            }\n            if (method.getName().equals(\"hasPermission\")) {\n                assertTrue(owned.get());\n                permissionChecked.set(true);\n                return true;\n            }\n            if (method.getName().equals(\"sendMessage\")) {\n                assertTrue(owned.get());\n                delivered.set(true);\n                return null;\n            }\n            return unexpected(method);\n        });\n    }\n\n    private static Plugin plugin() {\n        return proxy(Plugin.class, (method, arguments) -> unexpected(method));\n    }\n\n    private static EntityScheduler scheduler(SchedulerExecution execution) {\n        return proxy(EntityScheduler.class, (method, arguments) -> {\n            if (method.getName().equals(\"execute\")) {\n                return execution.execute(\n                        (Plugin) arguments[0],\n                        (Runnable) arguments[1],\n                        (Runnable) arguments[2],\n                        (Long) arguments[3]\n                );\n            }\n            return unexpected(method);\n        });\n    }\n\n    private static <T> T proxy(Class<T> type, Invocation invocation) {\n        return type.cast(Proxy.newProxyInstance(\n                Thread.currentThread().getContextClassLoader(),\n                new Class<?>[]{type},\n                (instance, method, arguments) -> invocation.invoke(method, arguments == null ? new Object[0] : arguments)\n        ));\n    }\n\n    private static Object unexpected(Method method) {\n        throw new AssertionError(\"Unexpected call: \" + method.getName());\n    }\n\n    @FunctionalInterface\n    private interface Invocation {\n        Object invoke(Method method, Object[] arguments) throws Throwable;\n    }\n\n    @FunctionalInterface\n    private interface SchedulerExecution {\n        boolean execute(Plugin plugin, Runnable action, Runnable retired, long delay);\n    }\n}\n""", encoding="utf-8")
